import { Component, inject } from '@angular/core';
import { CommonModule, CurrencyPipe } from '@angular/common';
import { CartService } from '../services/cart.service';
import { MatButtonModule } from '@angular/material/button';
import { ContactService } from '../services/contact.service';
import { ReplaySubject, takeUntil } from 'rxjs';
import { ContactForm } from '../models/contact-form';
import { FormsModule } from '@angular/forms';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { Router, RouterLink } from '@angular/router';
import { ROUTER_TOKENS } from '../app.routes';

@Component({
  selector: 'app-cart',
  standalone: true,
  imports: [
    CommonModule,
    CurrencyPipe,
    MatButtonModule,
    FormsModule,
    MatProgressSpinnerModule,
    RouterLink,
  ],
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.css']
})
export class CartComponent {
  readonly cartService = inject(CartService);

  readonly cartItemsPlusQuantity = this.cartService.cartItemsPlusQuantity;
  readonly subtotal = this.cartService.subtotal;
  readonly salesTax = this.cartService.salesTax;
  readonly total = this.cartService.total;

  readonly contactService = inject(ContactService);
  destroyed$ = new ReplaySubject<void>(1);

  model: ContactForm = {};
  submitted = false;
  loading = false;

  checkout() {
    this.loading = true;

    this.contactService.submitContactForm(this.model).pipe(
      takeUntil(this.destroyed$)
    ).subscribe(() => {
      this.submitted = true;
      this.loading = false;
      this.cartService.cartItems.set({});
    })
  }

  private router = inject(Router);
  close() {
    this.submitted = false;
    this.router.navigate([{ outlets: { [ROUTER_TOKENS.CART]: null } }]);
  }

  ngOnDestroy(): void {
    this.destroyed$.next();
    this.destroyed$.complete();
  }
}
<div class="cart-wrapper">
  <div class="cart-header"><span>
    Bethany's Pie Shop Shopping Cart
  </span><button
    mat-raised-button
  >close</button></div>
  <div class="cart-items-wrapper" *ngIf="!submitted; else formSubmitted">
    <div class="cart-item" *ngFor="let item of cartItemsPlusQuantity()">
      <div class="cart-item-image-wrapper">
        <img [src]="item.thumb" [alt]="item.title" />
      </div>
      <div class="cart-item-details-wrapper">
        <p class="cart-item-name">{{ item.title }}</p>
        <div class="quantity-selector-wrapper">
          <div class="quantity-selector">
            <button (click)="cartService.decrementCartItem(item)">-</button>
            <span>{{ item.quantity }}</span>
            <button (click)="cartService.addCartItem(item)">+</button>
          </div>
        </div>
      </div>
      <div class="cart-item-price-wrapper">
        <p class="cart-item-price">{{ item.price }}</p>
      </div>
    </div>
    <div class="cart-item" *ngIf="!cartItemsPlusQuantity().length">
      <div class="cart-item-details-wrapper">
        <p class="cart-item-name">You need pie! Go add some to your cart</p>
      </div>
    </div>
    <div class="totals-item">
      <div class="totals-details-wrapper">
        <div>Subtotal</div>
        <div>{{ subtotal() | currency }}</div>
      </div>
      <div class="totals-details-wrapper">
        <div>Shipping</div>
        <div>{{ 10 | currency }}</div>
      </div>
      <div class="totals-details-wrapper">
        <div>Sales Tax</div>
        <div>{{ salesTax() | currency }}</div>
      </div>
      <div class="totals-details-wrapper">
        <div>Total</div>
        <div>{{ total() | currency }}</div>
      </div>
      <div class="totals-details-wrapper">
        <button *ngIf="!loading" mat-button-raised
        (click)="checkout()">Checkout</button>
        <mat-spinner diameter="40" *ngIf="loading"></mat-spinner>
      </div>
    </div>
  </div>

  <ng-template #formSubmitted>
    <div class="cart-items-wrapper">
      <div class="totals-item" *ngIf="!loading">
        <div class="totals-details-wrapper">
          <div>Thank you for our order!</div>
        </div>
        <div class="totals-details-wrapper">
          <div>Order# 1664</div>
        </div>
        <div class="totals-details-wrapper">
          <button
          mat-button-raised
          >Close Cart</button>
        </div>
      </div>
    </div>
  </ng-template>
</div>
